return {
    ["line.conversation_alchemist_discipline_unlocked.1"] = { en = "The {discipline}'s Work is unlocked to you, {name}. The Crucible releases its guarded cut for that method. The shelf has more to offer you.", ja = "" },  -- TODO
    ["line.conversation_alchemist_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_alchemist_discipline_unlocked.3"] = { en = "You made this yours honestly. That is rarer here than the gear is. Take it.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_asked.1"] = { en = "Still here. So is the crate, and so is whatever the college is calling it this week.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_asked.2"] = { en = "It keeps. It should not have to keep.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_asked.3"] = { en = "Now, or on the way past. Choose...", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_asked.4"] = { en = "Go in with her.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_asked.5"] = { en = "Leave it standing.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.1"] = { en = "Stop there -- not for me, for the crate. Whatever the college told you is inside it, it is not a reagent, and it can hear every word we are saying.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.2"] = { en = "{posting}", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.3"] = { en = "Intact. They are always very specific about intact, and never once about alive. I have carried three of these off that road and I have never yet been given the word for what I was carrying.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.4"] = { en = "She is unarmed, {name}, and she came down here anyway. That tells you what she thinks it is worth.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.5"] = { en = "The crew that took it will not hand it back to a woman with a satchel. Come in with me and it walks out. Do that, and I go where you go after -- I would rather spend myself on people who ask what is in the box.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.6"] = { en = "We go in with her, or we leave it lying where it is. Choose...", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.7"] = { en = "Go in with her.", ja = "" },  -- TODO
    ["line.conversation_alchemist_errand_found.8"] = { en = "Leave it lying.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_01_outro.1"] = { en = "Straw is dry. Seals are whole. Nothing has gone off inside it.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_01_outro.2"] = { en = "The crate never left our hands.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_01_outro.3"] = { en = "Then you are the first. Four consignments have come off that road this season and three came back as a smell.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_01_outro.4"] = { en = "The college will be told it was recovered intact. They will not be told by whom, because they would try to hire you.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_01_outro.5"] = { en = "Come to the Crucible instead. Our counter is on the markets and it is open to you.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.1"] = { en = "Somebody in your company has been doing the Work. That is the only credential this house recognises.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.2"] = { en = "The Crucible refines your gear and brews your medicine. Poison and acid, coatings, elixirs, and auras that lend you what you are not.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.3"] = { en = "Lend it from whom?", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.4"] = { en = "From a source. Does a formula have feelings? Buy, friend, and be improved.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.5"] = { en = "Buy the tinctures and leave the philosophy on the shelf, {name}.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.6"] = { en = "As you wish. The shelf is open, and improvement is only ever a purchase away.", ja = "" },  -- TODO
    ["line.conversation_arcanum_discipline_unlocked.1"] = { en = "You have opened the {discipline}'s discipline, {name}. The Arcanum unseals what it holds for that study. The shelf is longer for you now.", ja = "" },  -- TODO
    ["line.conversation_arcanum_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_arcanum_discipline_unlocked.3"] = { en = "There is always more to learn on that road. Good. Take only what you will practise.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_asked.1"] = { en = "Twelve now. One of them came back with a friend, which means my count was wrong when I gave it to you and I would rather you heard that from me.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_asked.2"] = { en = "I will be on this step. The book is not going anywhere, and apparently neither am I.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_asked.3"] = { en = "Now, or on the way past. Choose...", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_asked.4"] = { en = "Take the room.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_asked.5"] = { en = "Leave it standing.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.1"] = { en = "Please do not go through that door yet. There are eleven of them in the reading room. I have counted them twice, from two positions, because once is not counting.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.2"] = { en = "{posting}", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.3"] = { en = "I have been sitting on this step for four hours working out how to take that room alone. The honest answer is that I cannot. That is not modesty, it is the arithmetic -- I did it properly and it comes out the same each time.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.4"] = { en = "Four hours on a step, and she did not go in. There are worse things to have in front of you, {name}.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.5"] = { en = "With your company in it, the arithmetic works. I would like the book. Rather more than the book, I would like to keep walking with people who check their numbers before they open a door.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.6"] = { en = "We take the room, or we leave the book to the diggers. Choose...", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.7"] = { en = "Take the room.", ja = "" },  -- TODO
    ["line.conversation_arcanum_errand_found.8"] = { en = "Leave the book.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_01_outro.1"] = { en = "Do not open it here. It has been under water since before the city had a wall.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_01_outro.2"] = { en = "There were four other parties down there digging for it.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_01_outro.3"] = { en = "There were six. Two of them are still down there.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_01_outro.4"] = { en = "You will want a table, light, and someone who can read it. The Arcanum has all three.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_01_outro.5"] = { en = "Our counter is on the markets. Come and use it. That is what it is for.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.1"] = { en = "Somebody in your company has been working. Practice leaves a mark, and this house is built to read it.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.2"] = { en = "The Arcanum wins the wars the crown cannot. Elements, wind-ups, hazards laid on a tile and left standing there.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.3"] = { en = "Everything here was made by somebody.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.4"] = { en = "By somebody, yes. Does it matter who, so long as it works? No one else can do what we do.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.5"] = { en = "Buy the long spells, {name}. A wind-up costs a turn you were going to spend anyway.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.6"] = { en = "The shelf is open. We ask only that what we sell be used as we intended, and we always know when it is not.", ja = "" },  -- TODO
    ["line.conversation_bastion_discipline_unlocked.1"] = { en = "You have earned the {discipline} road, {name}. The quartermaster has moved its gear onto your rack. The Watch keeps that kit for the ones who prove they can carry it.", ja = "" },  -- TODO
    ["line.conversation_bastion_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_bastion_discipline_unlocked.3"] = { en = "I trained beside a few who took that road. It is a good one. Do not let the rack outgrow the arm.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.1"] = { en = "Highwatch. Mountain post, top of the pass, warded on all four faces. It has been under siege for six weeks and without supply for twelve days.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.2"] = { en = "The column carrying its winter stores and its ward-salt is sitting at the bottom of that mountain and cannot get up it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.3"] = { en = "Then they are still standing. They were told to hold until relieved. They will be holding.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.4"] = { en = "Twelve days, Sworn. On a rock, in winter.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.5"] = { en = "I have met men who held forty on a well that had gone dry.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.6"] = { en = "...That is the assumption the order makes, yes.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.7"] = { en = "The doctrine is hers. Acedia's. Everything I know about holding a post I learned from her, and she has been dead fifteen years.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.8"] = { en = "This is not your line, {name}, and it is not your order.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.9"] = { en = "But I gave you two words in the ash and I meant them both. Come on.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.1"] = { en = "Twelve days. We'd stopped counting somewhere around the eighth.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.10"] = { en = "One thing before you go. Sixth wagon had a driver on it at the start and didn't at the end. Denhold. No people that I ever heard of.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.11"] = { en = "His share is sitting in my book with nowhere to go, and I am not carrying it back down that road to hand to nobody. You want it, it's yours. Choose...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.12"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.13"] = { en = "\"Put it in the Bastion's poor-box at Highwatch.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.14"] = { en = "\"We'll take it.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.15"] = { en = "Highwatch sent word down ahead of you. Twelve days without supply, and the column reached them.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.16"] = { en = "The order keeps a counter on the markets. It is open to you. Come and be armed properly next time.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.2"] = { en = "And they opened the gate to you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.3"] = { en = "Opened it? The sergeant came down the road on foot to meet the lead wagon. Wouldn't touch the flour. Went straight past me to the salt.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.4"] = { en = "Their wards were four days from going out. Four days, and then that mountain is just a wall with tired men on it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.5"] = { en = "I gave the last of our water to the boy on the wagon on the ninth and told him a relief was coming. I didn't believe it when I said it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.6"] = { en = "But they held.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.7"] = { en = "...Aye. They held.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.8"] = { en = "Forgive me, {name}. I'm no use at this part of it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.9"] = { en = "Somebody arrived. That's all I have ever wanted a story to say.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.1"] = { en = "A watchpost east of the river. There is nothing behind it worth defending. The villages moved off that land twenty years ago.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.2"] = { en = "The garrison has been told, in writing, that they may stand down.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.3"] = { en = "And they haven't.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.4"] = { en = "They have not.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.5"] = { en = "Good.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.6"] = { en = "Come and stand with them, {name}. You have been taking my word for what the order is. Today you can watch it done properly.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.1"] = { en = "The sergeant asked me when the relief was due. I told him I didn't know.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.10"] = { en = "\"He needs it more than we do.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.11"] = { en = "\"Take it. He's right.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.12"] = { en = "\"Rowan. You tell him. He'll believe a knight.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.13"] = { en = "Then he keeps it. Four days is four days.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.14"] = { en = "He is right. I hate that he is right.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.15"] = { en = "...He handed it over the moment I asked.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.16"] = { en = "He would not have, for you. I want you to know that.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.2"] = { en = "He said that was fine.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.3"] = { en = "He said it the way you'd say the weather was fine, {name}. Not bravely. It had just stopped being a question a long time ago.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.4"] = { en = "There is nothing behind that post. There has not been for twenty years. They know it better than the archive does. They can see the empty fields from the wall.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.5"] = { en = "It is what we teach. It is what I would have done.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.6"] = { en = "I have never watched it from outside before, and I do not know what I watched.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.7"] = { en = "He put his warding stores in front of me before we left. All of it. Four days' worth.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.8"] = { en = "He said it does more good on a road than on a wall nobody is coming to.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.9"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.1"] = { en = "Greywatch. Every knight in the order recites a doctrine named after that fort and I have never once stood in it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.2"] = { en = "There is nothing there, Sworn. It has stood empty fifteen years. The roof is in the courtyard.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.3"] = { en = "Then it won't mind me walking it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.4"] = { en = "I want to see the ground she chose to die on. That is all. Humour me, {name}.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.1"] = { en = "{name}. The bar. Look at the bar.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.10"] = { en = "\"Then it stays here.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.11"] = { en = "\"Load it up.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.12"] = { en = "\"They didn't want it, Rowan. You should have it.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.13"] = { en = "It stays. It is a grave, and that is grave goods.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.14"] = { en = "...Fine. It is only steel. She is not in it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.15"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.16"] = { en = "I trained on this rack. I know the spacing of it in the dark.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.17"] = { en = "All right. One. I will carry one of them, and I will carry it properly.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.2"] = { en = "It's on the ground. On the INSIDE. You cannot lift a gate-bar from the wrong side of a gate. That is the entire point of a bar.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.3"] = { en = "Someone in this fort opened it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.4"] = { en = "She died holding a gateway that was already standing open behind her. Fifteen years and nobody in the order has said that out loud.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.5"] = { en = "They let her name carry a doctrine and they never told a single one of us she was betrayed.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.6"] = { en = "I want the file. Whatever the archive kept on Greywatch, I want it in my hands.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.7"] = { en = "The armoury is still full, {name}. Racked and oiled and sixty spears deep.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.8"] = { en = "Forty-one people walked out of this fort and not one of them took a weapon with them.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.9"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.1"] = { en = "Somebody in your company has been fighting the way this order fights. That is the only reason this door is open to you.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.2"] = { en = "The Watch outfits those who hold. Plate a knight can be found standing in, and shields that outlast the arm behind them.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.3"] = { en = "I hold what's mine. Is that post enough?", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.4"] = { en = "It will do. We do not arm those who run, and you have not run yet.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.5"] = { en = "Take the plate first, {name}! Everything else on that rack only works while you are still on your feet.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.6"] = { en = "Hold until relieved, then. The shelf is yours, and the order remembers the ones who stay.", ja = "" },  -- TODO
    ["line.conversation_cafe_vendor_intro.1"] = { en = "You'll want feeding before you go. One order, {name}, and one is the whole of it. I'll not send a company up the hill on two breakfasts and a stomachache.", ja = "" },  -- TODO
    ["line.conversation_cafe_vendor_intro.2"] = { en = "One meal does that much?", ja = "" },  -- TODO
    ["line.conversation_cafe_vendor_intro.3"] = { en = "Mine does. Every one of yours eats it and every one of them carries it until the work is done. Read the board before you order. What's good for a long walk isn't what's good for a bad afternoon.", ja = "" },  -- TODO
    ["line.conversation_cathedral_discipline_unlocked.1"] = { en = "The {discipline}'s calling is open to you, {name}. What the Cathedral kept back for that path is on the shelf. Take what serves.", ja = "" },  -- TODO
    ["line.conversation_cathedral_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_cathedral_discipline_unlocked.3"] = { en = "The Light gives what is earned, and you earned this. Carry it gently.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_asked.1"] = { en = "It is still in there. It has hurt no one since you passed, which is not mercy -- there is no one left up here for it to hurt.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_asked.2"] = { en = "I will not press you. Ask, and I come.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_asked.3"] = { en = "Now, or on the way past. Choose...", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_asked.4"] = { en = "Ask her in.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_asked.5"] = { en = "Leave it standing.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.1"] = { en = "You can lower that. Whatever is in the mill will not be talked out of it -- but it does not have to be met with drawn steel from the doorway either, and I would rather it was not.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.2"] = { en = "{posting}", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.3"] = { en = "Laid to rest. That is the Cathedral's phrase and it means made quiet. I was raised on that phrase. I have stopped pretending the two are the same sentence.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.4"] = { en = "She wears their cloth and speaks of them like weather. Mark that, {name}.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.5"] = { en = "I carry no blade and I am not going to start. I can keep every one of you standing in that room and I cannot end what is in it -- that part is yours. Ask me, and you have everything I have. I will not take the work off you unasked.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.6"] = { en = "We ask her in, or we leave the mill to the dark. Choose...", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.7"] = { en = "Ask her in.", ja = "" },  -- TODO
    ["line.conversation_cathedral_errand_found.8"] = { en = "Leave the mill.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_01_outro.1"] = { en = "It is quiet. I stood at that gate an hour and it did not start again.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_01_outro.2"] = { en = "He was still turning the wheel. He did not know the water was gone.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_01_outro.3"] = { en = "They rarely do. That is the whole of the work, and most people will not go and do it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_01_outro.4"] = { en = "We keep a counter in the markets. Come to it. You have bought the right to be sold to.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.1"] = { en = "The fold is clear. That is what the Cathedral hired us for.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.10"] = { en = "I stood close enough to be certain. Three things happen at that altar.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.11"] = { en = "It takes, and you get a soldier who will die gladly and never know what is in him. It takes wrong, and you get a thing that is hunted afterwards, and called a demon out of the wild.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.12"] = { en = "Those. On the ground. In front of you. Every one of them was a child in that hall a season ago.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.13"] = { en = "I have put down three of those this year and been thanked for it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.14"] = { en = "And it kills. Most often, it simply kills. The body goes out the back and into the pit I showed you, and the register writes the child down as ascended to the Light.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.15"] = { en = "The roll of our glorious dead is a casualty list. Everyone reads it aloud on the feast day. Nobody has ever once counted it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.16"] = { en = "You knew this on the night you raised us. You held it a month.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.17"] = { en = "I held it until you could see it. Words would not have done this, and I would not have been believed.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.18"] = { en = "You are believed. Go on.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.19"] = { en = "How old are they when they take them?", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.2"] = { en = "Do not put your sword away yet. Look at them first. Properly, all of them.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.20"] = { en = "Six. Seven. Young enough not to remember being asked, because they were not.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.21"] = { en = "Mm. Then I know the shape of your house, priest, and I have never set foot in it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.22"] = { en = "I hid nine of them, before any of you knew me. I would have hidden ninety. That is the whole of my crime and I will not pretend to regret it in front of you.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.23"] = { en = "Then why has nobody in that building said a word?", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.24"] = { en = "Because almost nobody in that building knows. That is what I need you to understand, and it is the part that sounds like an excuse.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.25"] = { en = "The faith is real. The people in it are good. I have knelt beside them my whole life. It is a small circle around the rite, and they have kept it from the rest of us for a generation.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.26"] = { en = "If the Saint herself were told, plainly, with proof she could not put aside. It would end that afternoon. I believe that. I have to; it is the last thing I have that is not on fire.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.27"] = { en = "That is a great deal of weight on one woman's ignorance.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.28"] = { en = "Yes. It is.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.29"] = { en = "A rite that kills most of the ones it is done to is not a rite. It is a yield. Somebody is running it as a yield.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.3"] = { en = "They are small.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.30"] = { en = "...I have not let myself put it that way.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.31"] = { en = "Somebody keeps that register. Ledgers don't write themselves, and the hand that keeps one always knows what it's for.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.32"] = { en = "Then we go and read it ourselves.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.33"] = { en = "You will not be let near it, and I cannot walk back in to fetch it. I am fallen, and the word is theirs to give, and they gave it the day I did not come home.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.34"] = { en = "But you were never the faith's hand. You were hired by it and you are still standing here counting bodies, which makes you the only outfit in this country I could have said any of this to.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.35"] = { en = "Take me to that room. I only want to be standing somewhere the truth can still be carried.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.4"] = { en = "Yes.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.5"] = { en = "I have been carrying this since the night I brought you back, and I told you there were older names in the book. Sit down. I will give you the rest of it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.6"] = { en = "The children the faith takes in are sorted. Most are made anointed. The holy warriors you have cheered in the street. A few of us are kept back as clergy, and never blooded.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.7"] = { en = "Blooded. That is the word for it. There is a rite, and the rite puts something into a child, and what it puts in is not the Light.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.8"] = { en = "It is demon's blood.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.9"] = { en = "...You are certain.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.1"] = { en = "There is someone in your company doing the Light's work with no chapel to do it in. Word came up the road before you did.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.2"] = { en = "The faithful arm those who purge. Wards, relics, and water that burns what should not be walking.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.3"] = { en = "Do I have to kneel for them?", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.4"] = { en = "Kneel and the taking is made holy. Stand and it is only a purchase. Both are permitted.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.5"] = { en = "Take a ward, {name}. Ground you have closed is ground nothing crosses, and that is worth more than the sermon attached to it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.6"] = { en = "The shelf is open. The faith asks only that its gifts be used as it intended them.", ja = "" },  -- TODO
    ["line.conversation_colosseum_discipline_unlocked.1"] = { en = "The {discipline}'s work is on your card now, {name}. The stable stocks for the fighters who reach it, and you reached it. Spend, and spend well.", ja = "" },  -- TODO
    ["line.conversation_colosseum_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_colosseum_discipline_unlocked.3"] = { en = "Knew you had it in you. That gear's sharper than the house lets most touch. Go on, kit up.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_asked.1"] = { en = "Back already. I haven't moved -- there's nowhere I'd rather be than about to start.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_asked.2"] = { en = "Same opening. Same door. Whenever you're ready.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_asked.3"] = { en = "Now, or on the way past. Choose...", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_asked.4"] = { en = "Take the bout.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_asked.5"] = { en = "Leave her standing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.1"] = { en = "There you are. No house, no record, and you came all the way down here anyway. That's already the most interesting thing on the card.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.2"] = { en = "{posting}", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.3"] = { en = "Through that door it's me, and a netter the house booked to make it honest, and a crowd that doesn't know your name yet. That's the whole bout. I'm not going to dress it up for you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.4"] = { en = "She is telling you the composition of the room she means to beat you in, {name}. Nobody does that who is worried.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.5"] = { en = "I open the same way every time. Years of it. Nobody's read it yet and I've stopped waiting for somebody to, which is the only reason I still enjoy the job.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.6"] = { en = "Beat me and I'm yours. I go where I like -- and I'd like to go with whoever finally reads the swing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.7"] = { en = "We take the bout, or we leave her standing. Choose...", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.8"] = { en = "Take the bout.", ja = "" },  -- TODO
    ["line.conversation_colosseum_errand_found.9"] = { en = "Leave her standing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.1"] = { en = "Opening bout! On the sand. Nobody, no house, no record.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.2"] = { en = "And against them, on hire from no one in particular: Saber.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.3"] = { en = "On hire from whoever paid, thank you. It's a living.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.4"] = { en = "Right. You've not done this before, so. Two things, free, because I'd rather it was a bout than a mess.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.5"] = { en = "One. The crowd is not on your side and it is not against you. It does not know you exist yet. Stop listening to it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.6"] = { en = "Two.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.7"] = { en = "Everyone your size opens careful. Feels each other out, three or four exchanges, learns the range.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.8"] = { en = "I don't.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.1"] = { en = "The tunnel to the sand is that way. And a man in a very good coat has been watching you since the gate.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.2"] = { en = "House colors, no house name. A booking man, here to price the nobody before the crowd does. Choose...", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.3"] = { en = "Hear his offer.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.4"] = { en = "Walk past him to the sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.5"] = { en = "...forty in coin to open the card, win or lose, so long as the show is good. He's already written the ending. I take the money anyway.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.6"] = { en = "No handler, no leash, no debt at the door. Whatever happens on that sand is ours alone, and we walk to it steady.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.7"] = { en = "They put their opener up against a team with nothing behind it, and look at her: a mismatch in her favor and she's glad of it. Not hungry, not bored, just happy for the fight. No one's read her opening in years. Go be the first.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.1"] = { en = "Footsteps behind us. The same weight that put me on my back an hour ago. She followed us out.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.2"] = { en = "Easy, knight. If I meant you harm I'd not announce it with my boots.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.3"] = { en = "Saber. That's the name the card gives me, and it'll do. You'll have heard the house one shouted over the sand. Forget that one. It was rented.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.4"] = { en = "I open every bout the same way, and no one has read it in years. You two did, and I had more fun losing that than I've had winning since I can remember. You didn't flinch at the crowd, you didn't flinch at me, and nobody paid you to stand there.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.5"] = { en = "{name}. No house, no handler, no leash at the gate. Someone will tell you that's a weakness before the week's out. It isn't. On that sand it is the only thing worth owning.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.6"] = { en = "There is a reckoning owed under this arena. Its patron has eaten better fighters than me, one at a time, because one at a time is how she likes them. I cannot reach her alone. You are the first outfit I've met that might.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.7"] = { en = "So. No coin this round, no booking, no ending written for me before the bell. Just the first fight in years I'd follow off the sand. I'm asking straight: take me on.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.8"] = { en = "You unseated a sworn knight in front of a house that wanted you to win, veteran. I would far rather have that swinging beside us than waiting on the next card.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.9"] = { en = "Then it's a team, and it has nothing behind it, and I have wanted that for longer than I'd say. Lead on. Let's see how far it goes.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.1"] = { en = "Someone kitted up for this card and never made it to the sand. Their bag's still here, straps cut in a hurry.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.2"] = { en = "Cleansing draughts. A couple of clearwater vials and a panacea besides. Choose...", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.3"] = { en = "Take the lot.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.4"] = { en = "Rowan. Why would a fighter bring these to a sword bout?", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.5"] = { en = "Because a house like the one we're drawn against doesn't win with the sword alone. It fields netters. They'll rope your legs and hold you still while the big blade winds up. Drink one the moment you're pinned and it cuts you loose. You get your step back before the swing lands. A panacea will do the same for whoever's caught beside you. Don't stand there roped, waiting for it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.6"] = { en = "Cut loose, then move. Understood. Let's not keep the veteran waiting.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.1"] = { en = "Enough. Enough! It's been years since anyone put me on my back on this sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.15"] = { en = "And the houses pay attention to who does the work. Mine has a counter on the markets. It is open to you now. Come and spend.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.2"] = { en = "I've watched this place feed fighters to its patron, one after another. I will not be fed. And you two. No house behind you, and you still put me down.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.3"] = { en = "Well fought. The Adventurers' Guild is always short of people who live through their first bout.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.4"] = { en = "You want the Demon Lord? So does everyone who's lost a home. But it is only strong because of its seven. Its generals, its appetites. Unmake them one by one, and the crown is hollow.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.5"] = { en = "Walk out slow. I'll catch you past the gate. There's a thing I mean to ask, and not with a booking man breathing on it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_intro.1"] = { en = "BEAT: the vendor gives the job. The Warlord fought under our banner once; bring him back, or bring him down.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_intro.2"] = { en = "BEAT: the avatar clocks that this one is a genuine bout, a named fighter on the other side, not a culling.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_intro.3"] = { en = "BEAT: Saber is alight. THIS is the thing she loves: house against a fighter with a name, honest, no padding.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_outro.1"] = { en = "BEAT: the avatar marks it. That was a real bout, the best kind, fought clean.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_outro.2"] = { en = "BEAT: Saber is happier than the player has seen her. The craft, the read, the moment; this is the whole reason she never left the sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_outro.3"] = { en = "BEAT: a beat of pure, unguarded trust in the sport. She has no idea yet what the arena she loves is built on, and the player is about to.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_intro.1"] = { en = "BEAT: the promoter is warm, generous. Your name is the gate now, so we have taken care of your undercard for you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_intro.2"] = { en = "BEAT: the avatar realises the padding is the same thing as slot 2, only this time it is being done FOR them, and nobody thought to ask.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_intro.3"] = { en = "BEAT: Saber says nothing yet, but the mirror lands on both of them: the house that isn't one has started behaving like the others because they are winning.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_outro.1"] = { en = "BEAT: Saber asks it straight. Do you mean to keep taking the top billing?, and makes clear she wants a real answer, not a shrug.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_outro.2"] = { en = "BEAT: the choice is the player's, and the scene leaves it standing rather than resolving it. The billing is how they get to Ira at all.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.1"] = { en = "Word reaches this stable before the fighters do. Somebody under your banner has been winning up close.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.2"] = { en = "So the shelf is yours. Steel, leathers, and the little cruelties that keep a fighter on the card one more week.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.3"] = { en = "What does the house take for that?", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.4"] = { en = "Nothing. A house takes a cut and I only take coin. You have no house behind you, which is the best thing about you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.5"] = { en = "Buy the heavy end of it, {name}. What he calls cruelty is a stun, and a stun is a turn nobody spends on you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.6"] = { en = "Win loud. The crowd keeps a name, and a name is the one thing here I cannot sell you.", ja = "" },  -- TODO
    ["line.conversation_descent_crown.1"] = { en = "You came a long way down to meet me. There is no me to meet.", ja = "" },  -- TODO
    ["line.conversation_descent_crown.2"] = { en = "Seven wants, and seven people who agreed to carry one each, because a want cannot walk about on its own. You went past every one of them to get here.", ja = "" },  -- TODO
    ["line.conversation_descent_crown.3"] = { en = "You did not know a single one of their names this morning. That is the part I like.", ja = "" },  -- TODO
    ["line.conversation_descent_crown.4"] = { en = "I have nothing to say to you that is mine. I never did. Come and take the last of it.", ja = "" },  -- TODO
    ["line.conversation_descent_envy.1"] = { en = "Hold still. I want to see which of you is worth having.", ja = "" },  -- TODO
    ["line.conversation_descent_envy.2"] = { en = "I will wear it in a moment, and I will do it perfectly. That has never once been the same as having it.", ja = "" },  -- TODO
    ["line.conversation_descent_gluttony.1"] = { en = "You are going further down. They all are.", ja = "" },  -- TODO
    ["line.conversation_descent_gluttony.2"] = { en = "I ate the last four who came through saying it. I could not describe one of them to you now. There is nothing in me that keeps things.", ja = "" },  -- TODO
    ["line.conversation_descent_greed.1"] = { en = "You came down here to be paid. Everyone who walks past me is on their way to being paid.", ja = "" },  -- TODO
    ["line.conversation_descent_greed.2"] = { en = "I am owed by everything that lives. I have never once spent any of it and I have never once been able to stop collecting.", ja = "" },  -- TODO
    ["line.conversation_descent_greed.3"] = { en = "What you are carrying is already mine. Bring it here.", ja = "" },  -- TODO
    ["line.conversation_descent_lust.1"] = { en = "You are holding something back. For the bottom, or for whatever you have decided is worse than me.", ja = "" },  -- TODO
    ["line.conversation_descent_lust.2"] = { en = "I will have it either way. It is the only thing I have ever been able to do.", ja = "" },  -- TODO
    ["line.conversation_descent_pride.1"] = { en = "Show me what you have brought.", ja = "" },  -- TODO
    ["line.conversation_descent_pride.2"] = { en = "I will know it the moment I see it. I always do. I have not been surprised in a very long time and I would like to be.", ja = "" },  -- TODO
    ["line.conversation_descent_sloth.1"] = { en = "You want the stair behind me. You could turn round instead. Nobody down here would hold it against you.", ja = "" },  -- TODO
    ["line.conversation_descent_sloth.2"] = { en = "I held a post once. Nobody came. You will find out what I found out, and it will take you about fifteen years.", ja = "" },  -- TODO
    ["line.conversation_descent_wrath.1"] = { en = "Do not make it quick. A quick blow is a blow somebody is holding back.", ja = "" },  -- TODO
    ["line.conversation_descent_wrath.2"] = { en = "I have had a lifetime of being handled. Come and hit me properly.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.1"] = { en = "Stop here, {name}. That's a demon champion.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.2"] = { en = "It won't go down the way the others did, and the small ones will throw themselves at us to keep us off it.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.3"] = { en = "Cut it down and the rest stop mattering. Stay out of its reach and let it come to us.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.5"] = { en = "The report said imps. That thing came up out of the breach with the rest of them trailing after it.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.1"] = { en = "A shrine, still standing with the whole block burned around it.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.2"] = { en = "There's a censer left burning on the stone. We can carry it, or we can pour out what oil is left and dress our wounds with it. Choose...", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.3"] = { en = "Take the censer.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.4"] = { en = "Tend our wounds and move on.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.5"] = { en = "Keep it next to whatever you mean to swing. The smoke gets into the steel, and these things do not like being touched by the dawn.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.6"] = { en = "Patched up. We leave the censer for whoever comes through here after us.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.7"] = { en = "Now let's keep moving. There's more of this quarter to clear.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.1"] = { en = "Hold. Someone's under that wall, hurt and trying not to make a sound.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.2"] = { en = "Easy. We're not with the things that did this.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.3"] = { en = "Take the purse.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.4"] = { en = "Share what we're carrying, and take the lens.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.5"] = { en = "She pressed it on us and wouldn't hear otherwise. Said coin buys nothing in a quarter with no one left to sell.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.6"] = { en = "Not much to spare, and she took it kindly. Look through that lens and a demon's satchel keeps nothing back.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.7"] = { en = "An apothecary, before all this. She can make the square on her own now. Let's keep clearing, {name}.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.8"] = { en = "She's an apothecary, and she's already telling us the trick of them: mark one before you strike and you'll see where its guard runs thin. Keep that beside the bow and it'll work.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.9"] = { en = "She's got a purse she can't spend and a lens she can't carry. We can take the coin, or leave her our rations and take the glass. Choose...", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_discipline_unlocked.1"] = { en = "You walk the {discipline}'s trail now, {name}. The Lodge sets out gear for the ones who get this far. It is yours to draw.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_discipline_unlocked.3"] = { en = "That path knows when to stop. Take the kit. Remember the lesson with it.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_asked.1"] = { en = "It moved north while you were away. It is thinner. That is worse, not better -- a thin one eats sooner.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_asked.2"] = { en = "Once. My terms have not changed and they are not going to.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_asked.3"] = { en = "Now, or on the way past. Choose...", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_asked.4"] = { en = "Take her terms.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_asked.5"] = { en = "Leave it standing.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.1"] = { en = "Down. Lower than that. The boars have your scent already and they will reach you a long time before the stag does.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.2"] = { en = "{posting}", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.3"] = { en = "Antlers on a wall. That is what the Lodge wants and it is not why I have been sitting in this wood for nine days.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.4"] = { en = "Nine days, and a wolf that has not left her side. She is not the one being hunted here, {name}.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.5"] = { en = "It stopped being a stag two winters ago. It takes and it takes and the wood has gone quiet behind it -- so it comes down once, and nothing else in here does. Those are my terms and I do not move off them.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.6"] = { en = "Agree to that and my wolf goes in first and I go after her. Agree to it and I will walk you out of this wood, and further than that if you are going.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.7"] = { en = "We take it on her terms, or we leave the wood alone. Choose...", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.8"] = { en = "Take her terms.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_errand_found.9"] = { en = "Leave the wood.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_01_outro.1"] = { en = "Set them down. No, on the floor. I want to see how they stand.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_01_outro.2"] = { en = "Fourteen points. I have been telling them twelve for nine years.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_01_outro.3"] = { en = "It walked out of the fog and stopped. It had a look at us first.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_01_outro.4"] = { en = "It always does. That is why it is on the wall and not in a pot.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_01_outro.5"] = { en = "The Lodge keeps a counter in the markets. It is open to you now. Ask for me by the wall.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.1"] = { en = "There is a hunter in your company. The wood tells us that before you do.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.2"] = { en = "The Lodge clears the beasts that would eat your children and feeds your town on what is left. Honest work, honest coin.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.3"] = { en = "Never? Not one day in the year?", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.4"] = { en = "The wild always makes more game. That is the mercy of it. There is always another beast worth killing.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.5"] = { en = "Take a bow and the traps together, {name}. Half of what they sell here does nothing without the other half beside it.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.6"] = { en = "Draw what you need. Rank up, and one day they carve your name on that wall.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.1"] = { en = "That's the last of rift raff.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.2"] = { en = "The champion wasn't in the report but you did well to take it down.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.3"] = { en = "This is what happens when the guild fails to clear enough of The Rift.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.4"] = { en = "The deep floors get left alone, and whatever gathers down there comes up here.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.5"] = { en = "Let's collect our pay and see what work The Rift is offering, {name}.", ja = "" },  -- TODO
    ["line.conversation_prologue_ruins.1"] = { en = "Not too bad for your first job, but there's no time to rest.", ja = "" },  -- TODO
    ["line.conversation_prologue_ruins.2"] = { en = "Let's move to clear out the remaining demons and find survivors.", ja = "" },  -- TODO
    ["line.conversation_prologue_village.1"] = { en = "The demons that breached through the rift are up ahead, {name}.", ja = "" },  -- TODO
    ["line.conversation_prologue_village.2"] = { en = "They look like simple imps, so the guild report seems accurate.", ja = "" },  -- TODO
    ["line.conversation_prologue_village.3"] = { en = "Strike before they start to notice us. Watch this!", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.1"] = { en = "Four houses dig that hole and not one of them trusts the other three to say what came out of it. So they pay me to say it. Everything that comes up unnamed comes up here.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.10"] = { en = "Not on this counter.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.11"] = { en = "No. I checked.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.12"] = { en = "How long until you can do it without the stone?", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.13"] = { en = "I still use the stone.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.14"] = { en = "You do not have to name all of them. Name what you will carry, and sell the rest before the shelf forgets them.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.15"] = { en = "That is an assayer's stone. My college kept one and never once used it honestly.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.16"] = { en = "Put it on the stone when you are ready. I am here all day and most of the night.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.2"] = { en = "You can tell what a thing is by looking at it?", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.3"] = { en = "By the mark it leaves on the stone. I charge for the work, {name}, not for the answer. You pay the same whether I like what I find or not.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.4"] = { en = "And if you would rather not know, I will take it off you for what the work would have cost. I keep the last few on the shelf. Wanting one back costs more than I paid, which is the price of having changed your mind.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.5"] = { en = "Name the blades first, {name}. A coat you cannot name will still stop a blow. A blade you cannot name does nothing at all.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.6"] = { en = "Or you could swing it once and find out.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.7"] = { en = "People have. I have named what was left of two of them.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.8"] = { en = "You hold other people's things and you give them back whole. That is a good trade to be in.", ja = "" },  -- TODO
    ["line.conversation_touchstone_vendor_intro.9"] = { en = "I have seen a weigher put a thumb on a scale. Both thumbs, once.", ja = "" },  -- TODO
    ["line.conversation_tutorial_city.1"] = { en = "{select} to take the stair down.", ja = "" },  -- TODO
    ["line.conversation_tutorial_city.2"] = { en = "{select} the Rift. The stair down is inside.", ja = "" },  -- TODO
    ["line.conversation_tutorial_city.3"] = { en = "{select} {door}", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.1"] = { en = "Walk to the chest ahead. Use WASD, the arrow keys, or click a tile.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.2"] = { en = "Open your loadout to see what you found.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.3"] = { en = "{select} an item in your stash to equip it to a hero.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.4"] = { en = "A shield changes what Wait does: end the turn braced instead of idle.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.5"] = { en = "Armor answers a kind of damage. This one drinks fire, and nothing else.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.6"] = { en = "This one has no action to press. It sits in a cell and works on its own.", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.1"] = { en = "The Tally", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.2"] = { en = "Beside the stair is a count of what is forming on the floors you have left behind. Nothing down there is born -- it forms, and it does not stop.\n\nClimb out early and the count rises by {stair}. Lose the company and it rises by {wipe}. Every new floor you reach takes one back off, and sealing a circle takes off {seal}.\n\nFill all {max} marks and what is below stops waiting to be found. It comes up the stair on its own -- which is what happened to Bellmere.", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.3"] = { en = "Tactics", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.4"] = { en = "Your company can be taught to fight on its own.\n\nThis tab gives each body a list of rules, read top to bottom on its turn -- who to strike, when to fall back, what to save its breath for. A body with no rule it can obey simply waits for you.\n\nIn a fight, Auto hands the turn to those rules. Turn it off at any time and the company is yours again. Nothing is decided that you cannot take back.", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.5"] = { en = "Classes", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.6"] = { en = "Every body in your company stands in one class, and that is what its levels buy -- what a knight gains on the way up is not what a rogue gains.\n\nA class climbs by being fought in: every action banks technique against the house the thing in the hand belongs to. Levels in a house open the classes beyond it, and a class still shut stands in the list with its name and the level that opens it, so there is always something to climb towards.\n\nChanging class is free and takes nothing back. Levels already earned stay earned -- a change costs you the levels ahead, never the ones behind -- so it is a choice you can afford to make early.", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.7"] = { en = "A to continue", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.8"] = { en = "Tap to continue", ja = "" },  -- TODO
    ["line.conversation_tutorial_notes.9"] = { en = "Click, or press Enter to continue", ja = "" },  -- TODO
    ["line.conversation_tutorial_recruit.1"] = { en = "Somebody is standing at that end, with work of her own to ask for. Walking up to hear it costs us nothing. Doing the job she names is what brings her into the company.", ja = "" },  -- TODO
    ["line.conversation_tutorial_recruit.2"] = { en = "She is waiting on the far side of that door, and the work she asked for is the way through it. Win that fight and she comes out with us.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.1"] = { en = "Close the distance and strike without fear, {name}!", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.10"] = { en = "{select} on the lit tile to move there.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.11"] = { en = "{select} on Clear Out in your grid to ready it.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.12"] = { en = "{select} on your own tile to spin.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.13"] = { en = "{select} on Jolt to ready it. Its cost is purple: that is mana, not stamina.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.14"] = { en = "{select} on the grunt to jolt it.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.15"] = { en = "{select} on the grunt to strike it. Its card slid down the order, so you act before it does.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.2"] = { en = "There's more to the north. Slay them both before they do even more damage.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.3"] = { en = "Now take it in hand.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.4"] = { en = "Turn on your heel, {name}. Open them both at once.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.5"] = { en = "That big one is about to strike, use your magic, {name}!", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.6"] = { en = "Let it have the spark. It will not know which way it is facing.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.7"] = { en = "While it's stunned, {name}. Let's finish this!", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.8"] = { en = "Not that, {name}. Do as I showed you.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.9"] = { en = "{select} on the imp to move in range and attack with your weapon.", ja = "" },  -- TODO
    ["line.conversation_tutorial_wound.1"] = { en = "They were carried out of that fight. The dark band on their bar stays held back until we are above ground again - or until we spend a camp binding it instead of resting.", ja = "" },  -- TODO
    ["line.conversation_undercroft_discipline_unlocked.1"] = { en = "The {discipline}'s trade is yours now, {name}. The firm keeps stock off the open book for a hand that reaches it, and you reached it. Quietly, mind.", ja = "" },  -- TODO
    ["line.conversation_undercroft_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_undercroft_discipline_unlocked.3"] = { en = "Took me years to get shown that rack. You did it faster. Don't get sloppy with it.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_asked.1"] = { en = "Still counting. He has not moved, and neither have the names in there.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_asked.2"] = { en = "Every day that door stays shut is a day somebody up top still owes. Whenever you like. Not slower than that.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_asked.3"] = { en = "Now, or on the way past. Choose...", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_asked.4"] = { en = "Open it.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_asked.5"] = { en = "Leave it standing.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.1"] = { en = "You are loud. Be loud further back for a moment -- there is a man behind that door who counts footsteps for a living and he is very good at it.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.2"] = { en = "{posting}", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.3"] = { en = "Two keys, three doors, and the Undercroft would prefer you did not sit down and do that sum. The third door is the keeper. He does not open politely for me and he will not open politely for you.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.4"] = { en = "She knows the count of the doors and the name of the man. She has been inside, {name}.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.5"] = { en = "So let us be clear before it is open, because after is too late to be clear. The gold is yours -- all of it, I will not touch a coin. What I want is the ledgers, and the ledgers are going in a fire, and everyone whose name is in them stops owing tonight.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.6"] = { en = "We open it on that understanding, or we walk away from the door. Choose...", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.7"] = { en = "Open it.", ja = "" },  -- TODO
    ["line.conversation_undercroft_errand_found.8"] = { en = "Walk away.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_01_outro.1"] = { en = "Two keys and a third door. I did wonder how you would take that.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_01_outro.2"] = { en = "You knew there were three.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_01_outro.3"] = { en = "I knew. I wanted to see what you did about the one I could not give you.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_01_outro.4"] = { en = "Most people come back and tell me the job was short a key. You came back with the box.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_01_outro.5"] = { en = "There is a stair off the markets with no sign on it. Take it. The shelf down there is yours to shop.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.1"] = { en = "There is a hand in your company who knows the trade. We hear about quiet work, friend. That is why this counter is open to you.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.2"] = { en = "No sign, no door you would notice, and you found us anyway. Everything on this floor belonged to somebody else once.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.3"] = { en = "And the people it belonged to?", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.4"] = { en = "Owed. Everyone is owed, up above. We only hold the note. That is not cruelty, that is the world.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.5"] = { en = "Buy from him and pay him in coin, {name}. Owe this house nothing.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.6"] = { en = "The floor is open. Everything is for sale, and everything is owed.", ja = "" },  -- TODO
